"use strict";

/**
 * @constructor
 * @classdesc Image loader gives you a way to load an image with showing a placeholder to the user while the image is still loading. You can adjust the appearance of placeholders with these CSS classes:
 * 	.imageloader-container - a container for all elements;
 * 	.imageloader-preview - strictly speaking, it's the placeholder;
 * 	.imageloder-img - loading image.
 * @param {string} altText The attribute 'alt' for the image element.
 * @param {number[2]=} sizes Width and height of the placeholder. By default, it uses values from CSS.
 * @param {string=} loadingLabel You can change or localize a title on the placeholder. By default, it uses 'Loading…'.
 * @author Kozalo <kozalo@yandex.ru>
 * @copyright Kozalo.Ru, 2016
 */
var ImageLoader = function(altText, sizes, loadingLabel) {
	loadingLabel = loadingLabel || 'Loading…';

	let container = document.createElement('div');
	container.className = 'imageloader-container';

	if (sizes !== undefined) {
		container.style.width = sizes[0] + 'px';
		container.style.height = sizes[1] + 'px';
	}

	let preview = document.createElement('div');
	preview.className = 'imageloader-preview';
	preview.appendChild(document.createTextNode(loadingLabel));

	let image = new Image();
	image.className = 'imageloader-img';
	image.alt = altText;

	container.appendChild(preview);
	container.appendChild(image);


	// Member variables
	this.container = container;
	this.preview = preview;
	this.image = image;
};


/**
 * Gets the container.
 * return {HTMLDivElement}
 */
ImageLoader.prototype.getElement = function() { return this.container; };

/**
 * Gets the image.
 * return {HTMLImgElement}
 */
ImageLoader.prototype.getImage = function() { return this.image; };


/**
 * Loads an image over the placeholder with animation.
 * @param {string} url URL to the image.
 * @param {function=} callback The callback is called at the end of animation.
 */
ImageLoader.prototype.load = function(url, callback) {	
	this.image.src = url;

	let that = this;
	
	this.image.addEventListener('load', function() {

		that.preview.style.opacity = 0;

		that.container.style.width = that.image.width + 'px';
		that.container.style.height = that.image.height + 'px';

		that.image.style.opacity = 1;

		if (callback !== undefined)
			callback();
	});
};
"use strict";

/**
 * @constructor
 * @classdesc Most pages are created with this class. You can customize the appearance with these CSS classes:
 * 	.page - a container for all elements;
 * 	.closer - a box-shadow around the image.
 * Or you can assign your own CSS class to any element, of course.
 * @param {int} number The number of the page.
 * @author Kozalo <kozalo@yandex.ru>
 * @copyright Kozalo.Ru, 2016
 */
var Page = function(number) {
	let ordinalNumber = Page.ordinalNumber++;

	let container = document.createElement('div');
	container.id = 'p' + number;
	container.className = 'page flexible';
	container.style.top = ordinalNumber + '00%';

	let imgLoader = new ImageLoader('Page ' + number);
	container.appendChild(imgLoader.getElement());
	let img = imgLoader.getImage();
	img.className += ' closer';

	// Member variables
	this.number = number;
	this.ordinalNumber = ordinalNumber;
	this.container = container;
	this.imgLoader = imgLoader;
	this.img = img;
};

Page.ordinalNumber = 0;
Page.setOrigin = function(number) { Page.ordinalNumber = number; }


/**
 * Sets a map for the page. It's used to add a few elements of interactivity to images: the user can make some decisions.
 * See the 'forks.js' file for more information.
 * @param {number[][]} ratios Array of arrays of numbers. Numbers are coordinates of the map. Maps usually have more than one area, so the array has arrays of coordinates for all areas.
 * @param {function[]} callbacks Callbacks for all areas. They are called when the user clicks on an area.
 */
Page.prototype.setMap = function(ratios, callbacks) {
	this.ratios = ratios;
	this.callbacks = callbacks;
};


/**
 * Gets the container.
 * @return {HTMLDivElement}
 */
Page.prototype.getElement = function() { return this.container; };

/**
 * Appends itself to the 'elem' as a child and starts the process of loading the image. Also, if this page has a map, recalculates coordinates of the map.
 * @param {HTMLElement} elem Any HTML element.
 */
Page.prototype.append = function(elem) {
	const src = 'images/pages/' + this.number + '.jpg';
	let that = this;

	elem.appendChild(this.container);

	if (this.ratios !== undefined)
		this.imgLoader.load(src, adjustMap);
	else
		this.imgLoader.load(src);


	function adjustMap() {
		const imageWidth = $(that.img).width();
		const imageHeigh = $(that.img).height();

		let coords = [];

		for (let i in that.ratios) {
			let ratios = that.ratios[i];

			for (let j = 0; j < ratios.length; j += 2)
				coords[i] += (imageWidth / ratios[j]) + "," + (imageHeigh / ratios[j+1]) + ",";
		}

		let map = document.createElement('map');
		map.name = 'f' + that.number;

		for (let i in coords) {
			let area = document.createElement('area');
			area.shape = 'poly';
			area.coords = coords[i];
			$(area).click(that.callbacks[i]);

			map.appendChild(area);
		}

		that.container.appendChild(map);
		that.img.useMap = '#' + map.name;
	}
};


/**
 * Scrolls the windows to itself.
 */
Page.prototype.scrollToSelf = function() {
	$('body, html').scrollTo(window.innerHeight * this.ordinalNumber);
};
