$.fn.scrollBy = function (y, callback) {
	let opts = {
		during: 700,
    	easing: 'easeOutQuint'
	};

	if (callback !== undefined)
		opts.complete = callback;

    return this.stop().animate({
        scrollTop: '+=' + y
    }, opts);
};

$.fn.scrollTo = function (y, callback) {
	let opts = {
		during: 700,
    	easing: 'easeOutQuint'
	};

	if (callback !== undefined)
		opts.complete = callback;

    return this.stop().animate({
        scrollTop: y
    }, opts);
};